import * as React from 'react';
import type { QAProps } from '@gravity-ui/uikit';
import type { Table } from '@tanstack/react-table';
import type { Virtualizer } from '@tanstack/react-virtual';
import type { HeaderGroup } from "../../types/base.js";
import type { BaseFooterRowProps } from "../BaseFooterRow/index.js";
import type { BaseHeaderRowProps } from "../BaseHeaderRow/index.js";
import type { BaseRowProps } from "../BaseRow/index.js";
import type { CanDeferOffscreenCellContent } from "./types.js";
import "./BaseTable.css";
export interface BaseTableProps<TData, TScrollElement extends Element | Window = HTMLDivElement> extends QAProps {
    /** The table instance returned from the `useTable` hook */
    table: Table<TData>;
    /** HTML attributes for the `<table>` element */
    attributes?: React.TableHTMLAttributes<HTMLTableElement>;
    /** HTML attributes for the `<tbody>` element */
    bodyAttributes?: React.HTMLAttributes<HTMLTableSectionElement>;
    /** CSS classes for the `<tbody>` element */
    bodyClassName?: string;
    /** Ref for the `<tbody>` element */
    bodyRef?: React.Ref<HTMLTableSectionElement>;
    /**
     * Allows first-paint deferral for horizontally offscreen cell content while adaptive row
     * virtualization realizes a row. Return `true` only for passive content whose delayed mount
     * cannot affect row or column geometry, focus, accessibility, or application side effects.
     */
    canDeferOffscreenCellContent?: CanDeferOffscreenCellContent<TData>;
    /** HTML attributes for the `<td>` elements inside `<tbody>` */
    cellAttributes?: BaseRowProps<TData>['cellAttributes'];
    /** CSS classes for the `<td>` elements inside `<tbody>` */
    cellClassName?: BaseRowProps<TData>['cellClassName'];
